<!-- Added: show the initial password to the admin creating the account -->
<script>
document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('reg-form');
    if (!form) { return; }
    var note = document.createElement('div');
    note.className = 'alert alert-info';
    note.style.marginBottom = '15px';
    note.innerHTML = '<i class="bi bi-key-fill"></i> <strong>Initial password:</strong> ' +
        '<code style="font-size:1rem;">nrtdc2023</code><br>' +
        '<small>Give this to the new user. They will be required to change it the first time they log in.</small>';
    form.parentNode.insertBefore(note, form);

    // The original page carries a stale line about needing verification.
    // Accounts are created already verified, so correct that text.
    document.querySelectorAll('p, small, span, div').forEach(function (el) {
        if (el.children.length === 0 &&
            /unable to log in until they have been verified/i.test(el.textContent)) {
            el.textContent = 'New accounts are ready to use immediately. The user must set their own password on first login.';
        }
    });
});
</script>
